select vcb.chapter_id, vcb.chapter_name, vcb.voc_id, vcb.voc_name as content, if(uvr.voc_id is null, 0, 1) reviewed, if(unr.voc_id is null, 0, 1) not_remember, vm.id as mid, vm.type, vm.inter_content from (select vcb.chapter_id from voc_chap_book vcb where vcb.book_id = #{bookId} and is_deleted = 0 group by vcb.chapter_id
) bc
inner join voc_chap_book vcb on vcb.book_id = #{bookId} and bc.chapter_id = vcb.chapter_id and vcb.is_deleted=0 left join voc_meaning vm on vm.voc_id = vcb.voc_id and vm.is_deleted = 0 left join user_voc_rev uvr on uvr.user_id = #{userId} and uvr.voc_id = vcb.voc_id and uvr.is_deleted = 0 left join user_not_remember unr on unr.user_id = #{userId} and unr.voc_id = vcb.voc_id and unr.is_deleted = 0
